contracts/LaunchpadFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./BondingCurveToken.sol";
import "./interfaces/IUniswapV2Router02.sol";
import "./interfaces/IUniswapV2Factory.sol";

/**
 * @title LaunchpadFactory
 * @dev Pump.fun-style launchpad with linear bonding curve, 3% tax, and automatic graduation.
 */
contract LaunchpadFactory is Ownable, ReentrancyGuard {
    // --- Constants ---
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant TAX_RATE = 300; // 3%
    uint256 public constant GRADUATION_THRESHOLD = 9 ether; // 9 ETH target
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 * 10**18; // 1B tokens
    // k calculated for 9 ETH at 800M tokens sold:
    // 9 * 10^18 = k * (800,000,000 * 10^18)^2 / 2
    // k = 18 * 10^18 / (64 * 10^16 * 10^36) = 0.28125 * 10^-34
    // We store k scaled by 10^18 to avoid precision loss, or just use the formula directly.
    // Let's use a simplified linear curve constant:
    // P = c * S
    // Cost = c/2 * (S_new^2 - S_old^2)
    // c = 2 * Target / S_max^2
    // c = 2 * 9e18 / (800e6 * 1e18)^2 = 18e18 / 640000e12 / 1e36 = 18 / 640000 * 1e-30
    // This is too small for standard uint256 math without scaling.
    // Let's use a scaling factor of 1e18 for the price calculation.

    // Virtual Liquidity Parameters
    // To match pump.fun exactly, we might want a virtual reserve model (x * y = k), 
    // but the user requested a LINEAR bonding curve.
    // Let's stick to the linear curve P = k * S.
    // We will use a scaling factor to handle the small k.
    uint256 public constant K_SCALE = 1e36; 
    // k_scaled = (2 * 9 * 10^18 * K_SCALE) / (800_000_000 * 10^18)^2
    // k_scaled = 18e54 / 64e52 = 1800 / 64 = 28 (approx)
    // Let's be precise:
    // S_max = 800,000,000 * 1e18 = 8e26
    // S_max^2 = 64e52
    // Target = 9e18
    // k = 2 * 9e18 / 64e52 = 0.28125e-34
    // If we multiply by 1e36 (K_SCALE), we get 0.28125 * 100 = 28.125
    // Let's use a larger scale to be precise. 1e40?
    // k_scaled_40 = 281250
    uint256 public constant K_SCALED = 281250; 
    uint256 public constant SCALE_FACTOR = 1e40;

    // --- State Variables ---
    IUniswapV2Router02 public immutable uniswapRouter;
    address public immutable weth;
    address public baseAsset; // address(0) for ETH
    uint256 public creationFee = 0.01 ether;
    address public feeRecipient;

    struct Launch {
        address creator;
        address token;
        uint256 tokensSold;
        uint256 ethRaised;
        bool graduated;
        bool active;
    }

    mapping(address => Launch) public launches; // token address -> Launch
    address[] public allLaunches;

    // --- Events ---
    event LaunchCreated(address indexed token, address indexed creator, uint256 timestamp);
    event Buy(address indexed token, address indexed buyer, uint256 amountIn, uint256 amountOut, uint256 fee);
    event Sell(address indexed token, address indexed seller, uint256 amountIn, uint256 amountOut, uint256 fee);
    event Graduated(address indexed token, address indexed pair, uint256 liquidityETH, uint256 liquidityTokens);

    constructor(address _uniswapRouter, address _feeRecipient) Ownable(msg.sender) {
        uniswapRouter = IUniswapV2Router02(_uniswapRouter);
        weth = uniswapRouter.WETH();
        feeRecipient = _feeRecipient;
    }

    // --- Core Logic ---

    function createLaunch(string memory name, string memory symbol) external payable nonReentrant returns (address) {
        require(msg.value >= creationFee, "Insufficient creation fee");

        // Deploy Token
        BondingCurveToken token = new BondingCurveToken(name, symbol, address(this));
        address tokenAddress = address(token);

        // Mint total supply to this contract
        token.mint(address(this), TOTAL_SUPPLY);

        // Initialize Launch
        launches[tokenAddress] = Launch({
            creator: msg.sender,
            token: tokenAddress,
            tokensSold: 0,
            ethRaised: 0,
            graduated: false,
            active: true
        });
        allLaunches.push(tokenAddress);

        // Handle Fee
        (bool success, ) = feeRecipient.call{value: creationFee}("");
        require(success, "Fee transfer failed");

        // Refund excess
        if (msg.value > creationFee) {
            (bool refundSuccess, ) = msg.sender.call{value: msg.value - creationFee}("");
            require(refundSuccess, "Refund failed");
        }

        emit LaunchCreated(tokenAddress, msg.sender, block.timestamp);
        return tokenAddress;
    }

    function buy(address tokenAddress, uint256 minTokensOut) external payable nonReentrant {
        Launch storage launch = launches[tokenAddress];
        require(launch.active, "Launch not active");
        require(msg.value > 0, "Amount must be > 0");

        // 1. Calculate Tax
        uint256 fee = (msg.value * TAX_RATE) / BASIS_POINTS;
        uint256 amountIn = msg.value - fee;

        // 2. Calculate Tokens Out (Linear Curve Integration)
        // Cost = k/2 * (S_new^2 - S_old^2)
        // We need to solve for S_new:
        // 2 * Cost / k = S_new^2 - S_old^2
        // S_new^2 = S_old^2 + (2 * Cost / k)
        // S_new = sqrt(S_old^2 + (2 * Cost / k))
        // tokensOut = S_new - S_old

        // Using scaled k: k = K_SCALED / SCALE_FACTOR
        // 2 * Cost / (K_SCALED / SCALE_FACTOR) = 2 * Cost * SCALE_FACTOR / K_SCALED

        uint256 sOld = launch.tokensSold;
        uint256 term = (2 * amountIn * SCALE_FACTOR) / K_SCALED;
        uint256 sNewSquared = (sOld * sOld) + term;
        uint256 sNew = sqrt(sNewSquared);
        uint256 tokensOut = sNew - sOld;

        require(tokensOut >= minTokensOut, "Slippage exceeded");
        require(launch.tokensSold + tokensOut <= 800_000_000 * 10**18, "Exceeds max supply");

        // 3. Update State
        launch.tokensSold += tokensOut;
        launch.ethRaised += amountIn;

        // 4. Distribute Fee (50% creator, 50% protocol)
        uint256 creatorFee = fee / 2;
        uint256 protocolFee = fee - creatorFee;

        (bool successCreator, ) = launch.creator.call{value: creatorFee}("");
        require(successCreator, "Creator fee failed");

        (bool successProtocol, ) = feeRecipient.call{value: protocolFee}("");
        require(successProtocol, "Protocol fee failed");

        // 5. Transfer Tokens
        BondingCurveToken(tokenAddress).transfer(msg.sender, tokensOut);

        emit Buy(tokenAddress, msg.sender, msg.value, tokensOut, fee);

        // 6. Check Graduation
        if (launch.ethRaised >= GRADUATION_THRESHOLD) {
            _graduate(tokenAddress);
        }
    }

    function sell(address tokenAddress, uint256 amountIn, uint256 minEthOut) external nonReentrant {
        Launch storage launch = launches[tokenAddress];
        require(launch.active, "Launch not active");
        require(amountIn > 0, "Amount must be > 0");

        BondingCurveToken token = BondingCurveToken(tokenAddress);
        require(token.balanceOf(msg.sender) >= amountIn, "Insufficient balance");

        // 1. Calculate ETH Out (Refund)
        // Refund = k/2 * (S_old^2 - S_new^2)
        // S_new = S_old - amountIn
        uint256 sOld = launch.tokensSold;
        uint256 sNew = sOld - amountIn;

        // Refund = k/2 * (sOld^2 - sNew^2)
        // Using scaled k: (K_SCALED / SCALE_FACTOR) / 2 * (...)
        // = (K_SCALED * (sOld^2 - sNew^2)) / (2 * SCALE_FACTOR)

        uint256 refund = (K_SCALED * ((sOld * sOld) - (sNew * sNew))) / (2 * SCALE_FACTOR);

        // 2. Deduct Tax
        uint256 fee = (refund * TAX_RATE) / BASIS_POINTS;
        uint256 amountOut = refund - fee;

        require(amountOut >= minEthOut, "Slippage exceeded");
        require(address(this).balance >= amountOut + fee, "Insufficient contract balance");

        // 3. Update State
        launch.tokensSold -= amountIn;
        launch.ethRaised -= refund;

        // 4. Transfer Tokens from Seller
        token.transferFrom(msg.sender, address(this), amountIn);

        // 5. Distribute Fee
        uint256 creatorFee = fee / 2;
        uint256 protocolFee = fee - creatorFee;

        (bool successCreator, ) = launch.creator.call{value: creatorFee}("");
        require(successCreator, "Creator fee failed");

        (bool successProtocol, ) = feeRecipient.call{value: protocolFee}("");
        require(successProtocol, "Protocol fee failed");

        // 6. Send ETH to Seller
        (bool successSeller, ) = msg.sender.call{value: amountOut}("");
        require(successSeller, "ETH transfer failed");

        emit Sell(tokenAddress, msg.sender, amountIn, amountOut, fee);
    }

    function _graduate(address tokenAddress) internal {
        Launch storage launch = launches[tokenAddress];
        launch.graduated = true;
        launch.active = false;

        BondingCurveToken token = BondingCurveToken(tokenAddress);

        // 1. Mint remaining tokens (200M + unsold from curve)
        uint256 tokensToMint = TOTAL_SUPPLY - token.totalSupply();
        if (tokensToMint > 0) {
            token.mint(address(this), tokensToMint);
        }

        // 2. Liquidity Amount
        // We use all raised ETH (minus fees already taken) and all remaining tokens
        uint256 ethLiquidity = address(this).balance; // Use all available ETH in contract? 
        // Note: The contract holds ETH from buys. Fees were already paid out.
        // But wait, the contract might hold ETH for other launches too!
        // We must track ethRaised per launch accurately.
        // However, in this simple model, we assume ethRaised tracks the net ETH available for this launch.
        // Let's use launch.ethRaised.
        ethLiquidity = launch.ethRaised;

        uint256 tokenLiquidity = token.balanceOf(address(this));

        // 3. Approve Uniswap
        token.approve(address(uniswapRouter), tokenLiquidity);

        // 4. Add Liquidity
        uniswapRouter.addLiquidityETH{value: ethLiquidity}(
            tokenAddress,
            tokenLiquidity,
            tokenLiquidity, // Min tokens
            ethLiquidity,   // Min ETH
            address(0),     // Burn LP tokens (send to 0x0)
            block.timestamp
        );

        // 5. Renounce Ownership of Token (optional, or transfer to creator?)
        // Pump.fun usually burns LP and renounces ownership.
        token.renounceOwnership();

        emit Graduated(tokenAddress, address(0), ethLiquidity, tokenLiquidity);
    }

    // --- View Functions ---

    function getLaunch(address token) external view returns (Launch memory) {
        return launches[token];
    }

    function getAllLaunches() external view returns (address[] memory) {
        return allLaunches;
    }

    function getAmountOut(uint256 amountIn, bool isBuy, uint256 currentSupply) external pure returns (uint256) {
        if (isBuy) {
            // Buy: Input ETH -> Output Tokens
            // fee = amountIn * 3%
            uint256 netIn = amountIn - (amountIn * 300 / 10000);
            // S_new = sqrt(S_old^2 + (2 * netIn * SCALE / K))
            uint256 term = (2 * netIn * SCALE_FACTOR) / K_SCALED;
            uint256 sNew = sqrt((currentSupply * currentSupply) + term);
            return sNew - currentSupply;
        } else {
            // Sell: Input Tokens -> Output ETH
            // Refund = K/2 * (S_old^2 - S_new^2) / SCALE
            uint256 sNew = currentSupply - amountIn;
            uint256 refund = (K_SCALED * ((currentSupply * currentSupply) - (sNew * sNew))) / (2 * SCALE_FACTOR);
            // fee = refund * 3%
            return refund - (refund * 300 / 10000);
        }
    }

    // --- Utils ---
    function sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }

    receive() external payable {}
}

contracts/MemeToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MemeToken
 * @dev ERC20 token with 3% buy/sell tax paid in FCWEED to holders
 * 
 * Features:
 * - 3% tax on all transfers (configurable)
 * - Tax collected and distributed in FCWEED tokens
 * - Tax exemptions for specific addresses (launchpad, owner, etc.)
 * - Owner can update tax parameters and FCWEED token address
 */
contract MemeToken is ERC20, Ownable, ReentrancyGuard {
    // Tax configuration
    uint256 public taxPercentage = 300; // 3% = 300 basis points (out of 10000)
    uint256 public constant MAX_TAX = 1000; // Maximum 10% tax
    uint256 public constant BASIS_POINTS = 10000;

    // FCWEED reward token
    IERC20 public fcweedToken;

    // Tax exemptions
    mapping(address => bool) public isTaxExempt;

    // Collected tax tracking
    uint256 public totalTaxCollected;

    // Events
    event TaxCollected(address indexed from, address indexed to, uint256 amount);
    event TaxPercentageUpdated(uint256 oldPercentage, uint256 newPercentage);
    event FcweedTokenUpdated(address indexed oldToken, address indexed newToken);
    event TaxExemptionUpdated(address indexed account, bool exempt);
    event TaxDistributed(uint256 amount);

    /**
     * @dev Constructor
     * @param name_ Token name
     * @param symbol_ Token symbol
     * @param totalSupply_ Total supply to mint
     * @param fcweedToken_ Address of FCWEED reward token
     * @param owner_ Owner address
     */
    constructor(
        string memory name_,
        string memory symbol_,
        uint256 totalSupply_,
        address fcweedToken_,
        address owner_
    ) ERC20(name_, symbol_) Ownable(owner_) {
        require(fcweedToken_ != address(0), "Invalid FCWEED token address");

        fcweedToken = IERC20(fcweedToken_);

        // Mint total supply to owner
        _mint(owner_, totalSupply_);

        // Exempt owner and this contract from tax
        isTaxExempt[owner_] = true;
        isTaxExempt[address(this)] = true;
    }

    /**
     * @dev Override transfer to implement tax mechanism
     */
    function _update(
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        // Skip tax for minting, burning, or exempt addresses
        if (from == address(0) || to == address(0) || isTaxExempt[from] || isTaxExempt[to]) {
            super._update(from, to, amount);
            return;
        }

        // Calculate tax
        uint256 taxAmount = (amount * taxPercentage) / BASIS_POINTS;
        uint256 amountAfterTax = amount - taxAmount;

        // Transfer tax to contract
        if (taxAmount > 0) {
            super._update(from, address(this), taxAmount);
            totalTaxCollected += taxAmount;
            emit TaxCollected(from, to, taxAmount);
        }

        // Transfer remaining amount to recipient
        super._update(from, to, amountAfterTax);
    }

    /**
     * @dev Distribute collected tax as FCWEED rewards to holders
     * @param fcweedAmount Amount of FCWEED to distribute
     * @param recipients Array of recipient addresses
     * @param amounts Array of amounts for each recipient
     */
    function distributeTaxRewards(
        uint256 fcweedAmount,
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external onlyOwner nonReentrant {
        require(recipients.length == amounts.length, "Array length mismatch");
        require(recipients.length > 0, "No recipients");

        uint256 totalAmount = 0;
        for (uint256 i = 0; i < amounts.length; i++) {
            totalAmount += amounts[i];
        }
        require(totalAmount == fcweedAmount, "Amount mismatch");

        // Transfer FCWEED from owner to recipients
        for (uint256 i = 0; i < recipients.length; i++) {
            require(
                fcweedToken.transferFrom(msg.sender, recipients[i], amounts[i]),
                "FCWEED transfer failed"
            );
        }

        emit TaxDistributed(fcweedAmount);
    }

    /**
     * @dev Update tax percentage
     * @param newTaxPercentage New tax percentage in basis points
     */
    function setTaxPercentage(uint256 newTaxPercentage) external onlyOwner {
        require(newTaxPercentage <= MAX_TAX, "Tax too high");
        uint256 oldPercentage = taxPercentage;
        taxPercentage = newTaxPercentage;
        emit TaxPercentageUpdated(oldPercentage, newTaxPercentage);
    }

    /**
     * @dev Update FCWEED token address
     * @param newFcweedToken New FCWEED token address
     */
    function setFcweedToken(address newFcweedToken) external onlyOwner {
        require(newFcweedToken != address(0), "Invalid address");
        address oldToken = address(fcweedToken);
        fcweedToken = IERC20(newFcweedToken);
        emit FcweedTokenUpdated(oldToken, newFcweedToken);
    }

    /**
     * @dev Set tax exemption for an address
     * @param account Address to update
     * @param exempt Whether the address should be exempt
     */
    function setTaxExempt(address account, bool exempt) external onlyOwner {
        require(account != address(0), "Invalid address");
        isTaxExempt[account] = exempt;
        emit TaxExemptionUpdated(account, exempt);
    }

    /**
     * @dev Withdraw collected tax tokens (emergency function)
     * @param amount Amount to withdraw
     */
    function withdrawTax(uint256 amount) external onlyOwner {
        require(amount <= balanceOf(address(this)), "Insufficient balance");
        _transfer(address(this), owner(), amount);
    }

    /**
     * @dev Withdraw any ERC20 tokens sent to this contract
     * @param token Token address
     * @param amount Amount to withdraw
     */
    function withdrawToken(address token, uint256 amount) external onlyOwner {
        require(token != address(this), "Cannot withdraw own token");
        IERC20(token).transfer(owner(), amount);
    }
}

